def test_probe_rows_are_inserted_with_enum_values_in_column_order():
    conn = FakeConn()
    row = ProbeMetric(
        time=NOW, site_id="home-lab", target="dns:1.1.1.1", kind="dns",
        rtt_ms=31.5, jitter_ms=2.0, loss_pct=0, source="live",
